select * from (select a.REGIST_SEQNO registSeqno, a.RAISING_DATE raisingDate, a.RAISING_DATE termid, IFNULL(t2.pbc_code,a.PBC_PROD_ID) pbcProdId, IFNULL(t2.pbc_code,replace(a.PBC_PROD_ID,'INS','')) pbcPordIdOut, a.BUY_PLACE buyPlace, a.CUSTOMER_TYPE1 customerType1, a.BUY_PLACE buyPlaceCode, a.CUSTOMER_TYPE1 customerType1Code, a.CCY ccy, a.RAISING_AMTSUM raisingAmtsum, a.RAISING_AMTSUM_CNY raisingAmtsumCny, a.RAISING_QTY raisingQty, a.REDAMT redamt, a.REDAMT_CNY redamtCny, a.REDQTY redqty, a.ENDAMTSUM endamtsum, a.ENDAMTSUM_CNY endamtsumCny, a.ENDQTY endqty, a.PROD_VALUE prodValue, a.PROD_VALUE_CNY prodValueCny, a.UNIT_VALUE_TOTAL unitValueTotal, a.UNIT_VALUE_TOTAL_CNY unitValueTotalCny, a.PROD_END_YIELD prodEndYield, a.SEND_STATUS sendStatus, a.SUBMIT_TIME submitTime, a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, a.SUMIT_SEQ sumitSeq, a.STATUS_DATE statusDate, a.PBC_SUBMIT_DEADLINE pbcSubmitDeadline, a.SUBMIT_DEADLINE submitDeadline, a.STATUS status, a.CREATE_USER createUser, a.ORG_CODE orgCode, a.CREATE_DEPT createDept, a.CREATE_TIME createTime, a.UPDATE_USER updateUser, a.UPDATE_TIME updateTime, b.PROD_ID prodId, a.DATUUID datuuid, t2.PBC_CODE pbcCode from PBC_COL_PROD_RAISING_SUB a left join (select distinct PBC_PROD_ID,PROD_ID from pbc_col_prd_baseinfo_sub) b on a.PBC_PROD_ID = b.PBC_PROD_ID LEFT JOIN( SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status='E' AND code_type='01' )t2 ON t2.inside_prod_id=b.PROD_ID
a.SEND_STATUS ='01'
#{items,jdbcType=VARCHAR}
null) OR a.REGIST_SEQNO in (
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
and a.SEND_STATUS in
