mapper.update:
update PBC_COL_PROD_RAISING_SUB sub set SEND_STATUS = '03', SUBMIT_FEEDBACK_STATUS = '03', SUBMIT_TIME = now(), UPDATE_TIME = now() where 1=1
#{items,jdbcType=VARCHAR}
and sub.SEND_STATUS ='01'

update PBC_COL_PROD_RAISING_SUB sub set SEND_STATUS = '01', UPDATE_TIME = now(), SUBMIT_TIME = null, SUBMIT_FEEDBACK_STATUS = null where 1=1
#{items,jdbcType=VARCHAR}
and sub.SEND_STATUS ='03'

mapper.delete:
delete from PBC_COL_PROD_RAISING_SUB_HIS where PBC_PROD_ID in ( select t1.PBC_PROD_ID from ( select PBC_PROD_ID , rank() over (partition by PBC_PROD_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_COL_PROD_RAISING_SUB_HIS
select #{item.pbcProdId,jdbcType=CHAR}, #{item.raisingDate,jdbcType=CHAR}, #{item.buyPlace,jdbcType=CHAR}, #{item.customerType1,jdbcType=CHAR}, #{item.ccy,jdbcType=CHAR} from dual
) t1 where t1.ranknum = 1 )

mapper.select:
select prdposition.ENDDATE RAISING_DATE,/*募集日期（月末日期）*/ prdbaseinfo.PROD_ID PROD_ID,/*中债产品代码*/ prdbaseinfo.PBC_PROD_ID PBC_PROD_ID,/*人行产品代码*/ (case when prdposition.BUY_PLACE='710000' then '000158' when prdposition.BUY_PLACE='810000' then '000344' when prdposition.BUY_PLACE='820000' then '000446' else prdposition.BUY_PLACE end) as BUY_PLACE ,/*地区代码*/ (case when prdposition.BUY_PLACE in ('710000','810000','820000') then 'C0601' else prdposition.CUSTOMER_TYPE2 end) as CUSTOMER_TYPE1,/*客户一级类型*/ prdposition.ccy ccy,/*币种*/ prdbaseinfo.VDATE, ifnull(prdposition.DIRTYAMTSUM,0) RAISING_AMTSUM,/*当期申购金额=当期募集金额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ ifnull(prdposition.DIRTYQTY,0) RAISING_QTY,/*当期申购份额=当期募集份额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ /*非净值型产品赎回交易取值（01 赎回金额=金额，赎回份额=份额；02 赎回金额=份额，赎回份额=份额；03 赎回金额=金额，赎回份额=金额)*/ case when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '01' then ifnull(PRDPOSITION.REDAMT,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '02' then ifnull(PRDPOSITION.REDQTY,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '03' then ifnull(PRDPOSITION.REDAMT,0) else ifnull(prdposition.REDAMT,0) end as REDAMT,/*当期兑付/赎回金额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ case when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '01' then ifnull(PRDPOSITION.REDQTY,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '02' then ifnull(PRDPOSITION.REDQTY,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '03' then ifnull(PRDPOSITION.REDAMT,0) else ifnull(prdposition.REDQTY,0) end as REDQTY,/*当期兑付/赎回份额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ ifnull(prdposition.ENDAMTSUM_OTH,0) ENDAMTSUM,/*期末产品金额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ ifnull(prdposition.ENDQTYSUM,0) ENDQTY,/*期末产品份额，需另外按照产品代码、地区代码、客户类型、币种代码汇*/ (case prdbaseinfo.OPERATE_MODE when '1' then ifnull(maxyield.PROD_VALUE,1) when '3' then ifnull(maxyield.PROD_VALUE,1) else null end) PROD_VALUE,/*净值型产品期末净值*/ (case prdbaseinfo.OPERATE_MODE when '1' then ifnull(maxyield.UNIT_VALUE_TOTAL,1) when '3' then ifnull(maxyield.UNIT_VALUE_TOTAL,1) else null end) UNIT_VALUE_TOTAL,/*净值型产品期末累计净值*/ ifnull(maxyield.TDY_UNIT_VALUE_SUM,ifnull(maxyield.UNIT_VALUE_TOTAL,2)-1) UNIT_VALUE, /*(case prdbaseinfo.OPERATE_MODE when '3' then prdbaseinfo.HIGH_YIELD_ISSUE else null end) PROD_HIGH_YIELD,开放式非净值型产品预期最高收益率 (case prdbaseinfo.OPERATE_MODE when '3' then prdbaseinfo.LOW_YIELD_ISSUE else null end) PROD_LOW_YIELD,开放式非净值型产品预期最低收益率*/ maxyield.CCY YEILD_CCY,/*收益率币种*/ prdposition.ORG_CODE ORG_CODE, maxyield.sevenDayRate PROD_END_YIELD, prdbaseinfo.OPERATE_MODE, cdeal.SETTDATE_DATE CMDATE FROM PBC_MONTH_PRD_POSITION PRDPOSITION inner JOIN ( SELECT PROD_ID, PBC_PROD_ID, OPERATE_MODE, CASH_MANA_CATE, MDATE, VDATE, /*HIGH_YIELD_ISSUE, LOW_YIELD_ISSUE,*/ RANK() OVER (PARTITION BY PROD_ID ORDER BY IFNULL(UPDATE_TIME,CREATE_TIME) DESC) RANKNUM from PBC_COL_PRD_BASEINFO_SUB where PBC_PROD_ID is not null ) prdbaseinfo ON PRDPOSITION.PRODID = PRDBASEINFO.PROD_ID AND RANKNUM = 1 left join ( /*取离月末最近的净值和收益率，不需要判断CHANG_TYPE，默认净值型产品存净值，预期收益率产品存收益率*/ select YIELD.PROD_VALUE, YIELD.PROD_ID, YIELD.UNIT_VALUE_TOTAL, YIELD.TDY_UNIT_VALUE_SUM, YIELD.CCY, YIELD.SEVEN_DAY_RATE sevenDayRate, rank() over (partition by yield.PROD_ID,yield.ccy order by YIELD.CHANGE_DATE desc) ranknum/*按产品+币种维度分类，按变动日期降序排序取最大的日期的净值*/ FROM CHB_PRD_PERIODYIELD YIELD WHERE 1 =1 AND YIELD.STATUS != 'D' AND DATE_FORMAT(YIELD.CHANGE_DATE,'%Y-%m-%d') <= #{cdate,jdbcType=VARCHAR} ) maxyield on PRDPOSITION.PRODID = maxyield.PROD_ID and maxyield.ranknum = 1 left join( select DISTINCT PROD_ID,SETTDATE_DATE from CHB_PRD_DEAL WHERE TRADE_TYPE='16' AND STATUS IN ('E','M') ) cdeal on PRDPOSITION.PRODID=cdeal.PROD_ID where 1 =1 and DATE_FORMAT(prdposition.ENDDATE,'%Y-%m-%d') = #{cdate,jdbcType=VARCHAR} /****HXRHPTSJ-96 ZG04 产品存续期募集信息，只是产品发行成功无任何交易无任何余额，存续期募集生成了数据**/ and PRDPOSITION.DURATIONFLAG in ('01','02') /****HXRHPTSJ-96 ZG04 产品存续期募集信息，只是产品发行成功无任何交易无任何余额，存续期募集生成了数据**/
and (prdposition.BUY_PLACE not in('210200','330200','350200','370200','440300') or prdposition.BUY_PLACE is null)
#{prodid,jdbcType=VARCHAR}

select distinct
replace(PBC_PROD_ID,'INS','') PBC_PROD_ID ,mdate from pbc_col_prd_baseinfo_sub
where date_format(mdate,'%Y%m') <= #{date}
